const worldSentence=z=>{const nouns={'red squares':['red square','red squares'],'blue circles':['blue circle','blue circles'],'all present objects':['present object','present objects']}[z.restrictor];return z.quantifier==='every'?'Every '+nouns[0]+' is '+z.predicate:z.quantifier==='no'?'No '+nouns[0]+' is '+z.predicate:(z.quantifier==='some'?'Some':z.quantifier==='most'?'Most':'Exactly three')+' '+nouns[1]+' are '+z.predicate;};
const inkOn=rgb=>{const L=rgb.map(x=>x/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2).reduce((s,x,i)=>s+x*[.2126,.7152,.0722][i],0);return L>.179?[0,0,0]:[255,255,255];};
const ellipse=(s,x,y,rx,ry,st)=>s.poly(H.range(65,0,2*Math.PI).map(t=>[x+rx*Math.cos(t),y+ry*Math.sin(t)]),st);
function wrap(s,t,x,y,width=8.5,{size=12,color='ink',maxLines=12,...o}={}){
 const ctx=s.ctx;ctx.save();ctx.font=s._font({size});const max=Math.abs(s.X(x+width)-s.X(x)),lines=[];let line='';
 for(const word of String(t).split(/\s+/)){const joined=line?line+' '+word:word;if(ctx.measureText(joined).width<=max){line=joined;continue;}if(line)lines.push(line);line=word;while(ctx.measureText(line).width>max&&line.length>1){let n=1;while(n<line.length&&ctx.measureText(line.slice(0,n+1)).width<=max)n++;lines.push(line.slice(0,n));line=line.slice(n);}}
 if(line)lines.push(line);ctx.restore();const shown=lines.slice(0,maxLines);if(lines.length>maxLines)shown[shown.length-1]+='…';shown.forEach((q,i)=>text(s,q,x,y-i*size*1.45/s.sy,color,{size,baseline:'top',...o}));return shown.length*size*1.45/s.sy;
}
function box(s,title,body,x,y,w=8.4,h=1.8,color='teal'){
 s.rect(x,y-h,x+w,y,{fill:'panel',fillAlpha:1,color,width:1.2,radius:7});text(s,title,x+.25,y-.35,color,{size:11});wrap(s,body,x+.25,y-.65,w-.5,{maxLines:Math.max(1,Math.floor((h-.8)*s.sy/17.4))});
}
function ticks(a,b){const raw=(b-a)/4,p=10**Math.floor(Math.log10(raw)),step=[1,2,2.5,5,10].find(x=>x>=raw/p)*p,out=[];for(let j=Math.ceil(a/step);j<=Math.floor(b/step);j++)out.push([j*step,fmt(j*step)]);return out;}
const countTicks=b=>ticks(0,Math.max(1,b)).filter(([v])=>Number.isInteger(v));
function notice(s,message,color='muted'){
 s.o.axes=false;s.o.xticks=null;s.o.yticks=null;view(s);wrap(s,message,.8,6.5,8.4,{color,size:14});
}
function plot(s,series,{x=null,y=null,xticks=null,yticks=null}={}){
 s.o.axes='box';const points=series.flatMap(q=>q.p).filter(p=>p&&p.every(Number.isFinite));if(!points.length){notice(s,'No defined values in this state.');return;}
 let a=x?.[0]??Math.min(...points.map(p=>p[0])),b=x?.[1]??Math.max(...points.map(p=>p[0])),c=y?.[0]??Math.min(0,...points.map(p=>p[1])),d=y?.[1]??Math.max(0,...points.map(p=>p[1]));if(a===b){a-=.5;b+=.5;}if(c===d){if(c===0)d=1;else{c-=.5;d+=.5;}}const dx=b-a,dy=d-c;s.o.xticks=xticks??ticks(a,b);s.o.yticks=yticks??ticks(c,d);view(s,[a-.05*dx,b+.05*dx],[c-.07*dy,d+.07*dy]);for(const q of series){const p=q.p.filter(p=>p&&p.every(Number.isFinite));if(p.length>1&&q.connect!==false)s.path(p,{color:q.c??'teal',width:2.3,dash:q.dash??[]});if(q.dots)for(const v of p)s.dot(...v,{color:q.c??'teal',r:q.r??4,hollow:!!q.hollow});}
}
function relationPanel(s,table,n,{rows=n,cols=n,selected=[-1,-1]}={}){
 view(s);const left=2,bottom=1.4,size=5.6/n;
 for(let i=0;i<rows;i++)for(let j=0;j<cols;j++){const x=left+j*size,y=bottom+(n-1-i)*size,yes=!!table[n*i+j];s.rect(x,y,x+size*.9,y+size*.9,{fill:yes?'teal':'bg',fillAlpha:yes?.65:1,color:i===selected[0]&&j===selected[1]?'gold':'grid',width:i===selected[0]&&j===selected[1]?2.5:1,radius:3});if(yes)text(s,'✓',x+size*.45,y+size*.45,'ink',{align:'center',size:14});}
 for(let i=0;i<rows;i++)text(s,String(i+1),1.55,bottom+(n-.55-i)*size,'muted',{align:'center'});for(let j=0;j<cols;j++)text(s,String(j+1),left+(j+.45)*size,bottom-.4,'muted',{align:'center'});if(!rows||!cols)wrap(s,'The selected domain is empty.',1,4,8);text(s,'rows → columns',5,7.65,'muted',{align:'center',size:11});
 return{x:left,y:bottom,size,n};
}
function matrixTap(s,n,apply){s.onClick((x,y)=>{const left=2,bottom=1.4,size=5.6/n,j=Math.floor((x-left)/size),i=n-1-Math.floor((y-bottom)/size);if(i>=0&&i<n&&j>=0&&j<n&&x-left-j*size<size*.9&&y-bottom-(n-1-i)*size<size*.9)apply(i,j);});}
function referenceFlow(s,z){
 view(s);[0,1,2].forEach((i)=>{const y=6.8-i*2.1,active=i===z.left||i===z.right;s.dot(1,y,{r:active?8:5,color:i===2?'muted':'blue',hollow:!active});text(s,z.expressions[i],1.5,y,'ink',{size:12});text(s,z.senses[i],1.5,y-.48,'muted',{size:10.5});if(i<2){s.path([[5.6,y],[6.3,y],[7.6,4.7]],{color:active?'teal':'grid',width:active?2.5:1});}else{s.line(5.8,y,7.2,y,{color:'muted',dash:[4,4]});text(s,'no referent',7.4,y,'muted',{size:10.5});}});s.dot(8.1,4.7,{r:24,color:'gold'});s.dot(8.1,4.7,{r:21,color:'orange',alpha:.35});text(s,'Venus',8.1,3.6,'ink',{align:'center'});text(s,'Two presentations, one planet',5,.7,'muted',{align:'center',size:11});
}
export function senseWidget(v){
 const left=v.select('first expression',['Morning Star','Evening Star'],'Morning Star'),right=v.select('second expression',['Morning Star','Evening Star'],'Evening Star'),morning=v.toggle('ledger: accepts dawn claim',true),evening=v.toggle('ledger: accepts dusk claim',false),A=panel(v,'Names, presentations and a shared referent'),B=panel(v,'A stipulated belief ledger'),C=panel(v,'Identity and substitution are different tests');let z;
 v.render(()=>{z=H.reference({left:left.value==='Morning Star'?0:1,right:right.value==='Morning Star'?0:1,beliefs:[morning.value,evening.value,true]});referenceFlow(A,z);view(B);box(B,'DAWN PRESENTATION',boolWord(z.beliefs[0]),.8,6.8,8.4,1.8,'blue');box(B,'DUSK PRESENTATION',boolWord(z.beliefs[1]),.8,4.4,8.4,1.8,'orange');wrap(B,'These are authored acceptance entries, not observed beliefs.',.9,1.5,8.2,{color:'muted',size:11});view(C);box(C,'ORDINARY IDENTITY',boolWord(z.identity),.8,6.8);box(C,'REPORT PRESERVED?',boolWord(z.substitutionPreservesReport),.8,4.4,8.4,1.8,'orange');wrap(C,'Co-reference alone does not require these two ledger entries to agree.',.9,1.5,8.2,{color:'muted',size:11});});
 v.legend([['blue','dawn presentation'],['orange','dusk presentation / belief contrast'],['gold','shared Venus referent']]);v.readout(()=>`Both descriptions denote Venus in this example. Identity is ${boolWord(z.identity)}; the presentations ${z.sameSense?'coincide':'differ'}. The selected belief reports are ${z.indirect.map(boolWord).join(' and ')}. Entries are stipulated independently to illustrate a possible substitution failure; changing a name does not automatically change a report. This is a semantic diagram, not an astronomical sky simulation.`);
}
