 const subject=v.select('subject',H.NAMES,'Ada'),object=v.select('object',H.NAMES,'Bo'),neg=v.toggle('negate the whole sentence',false),step=int(v,'composition step',0,4,4),row=int(v,'subject row to edit',1,3,1),col=int(v,'object column to edit',1,3,2);let relation=H.RELATION.slice();const A=panel(v,'Typed syntax and function application'),B=panel(v,'Greets relation · tap a cell to toggle'),C=panel(v,'The computed verb-phrase extension');let z;
 const flip=(i,j)=>{relation[3*i+j]=1-relation[3*i+j];v.invalidate();};matrixTap(B,3,flip);v.button('Toggle selected greeting',()=>flip(row.value-1,col.value-1));v.shareState('greeting relation',{get:()=>relation.slice(),validate:q=>H.validMatrix(q,3),set:q=>{relation=q.slice();v.invalidate();}});
