 v.render(()=>{z=H.truthWorld({world,quantifier:q.value,restrictor:restrictor.value,predicate:predicate.value});shapes(A,z,selected.value-1);view(B);text(B,'object',1,7.2,'muted',{align:'center',size:11});text(B,'in A',4.2,7.2,'blue',{align:'center',size:11});text(B,'in B',7.5,7.2,'teal',{align:'center',size:11});for(let i=0;i<8;i++){const y=6.5-.7*i;text(B,String(i+1),1,y,'ink',{align:'center'});for(const[c,set]of[[4.2,z.A],[7.5,z.B]])B.dot(c,y,{r:5,color:set.includes(i)?'teal':'muted',hollow:!set.includes(i)});if(z.counterexamples.includes(i))B.rect(.6,y-.25,8.5,y+.25,{color:'orange',width:1.5});}view(C);box(C,({every:'EVERY A IS B',some:'SOME A ARE B',no:'NO A IS B',most:'MOST A ARE B','exactly three':'EXACTLY THREE A ARE B'})[z.quantifier],boolWord(z.truth),.8,6.9,8.4,1.9,z.truth?'teal':'orange');wrap(C,'A = {'+z.A.map(i=>i+1).join(', ')+'}',1,4.4,8,{color:'blue'});wrap(C,'A ∩ B = {'+z.intersection.map(i=>i+1).join(', ')+'}',1,3.4,8,{color:'teal'});wrap(C,z.vacuous?'The restrictor is empty: this universal is vacuously true.':'Counterexamples to every: {'+z.counterexamples.map(i=>i+1).join(', ')+'}',1,2.3,8,{color:'muted'});});
